package com.jgeted.sagadyssey.social.religion;

import com.jgeted.sagadyssey.npc.brain.fieldwork.FieldworkStorage;
import com.jgeted.sagadyssey.social.institution.*;
import com.jgeted.sagadyssey.worldsim.rights.*;
import com.jgeted.sagadyssey.worldsim.transfer.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ReligionDataTest{
    private final UUID id=UUID.randomUUID(),person=UUID.randomUUID();
    private FieldworkStorage store(int x){return new FieldworkStorage("minecraft:overworld",new BlockPos(x,1,0),UUID.randomUUID(),SubjectRef.institution(id),AccessPolicy.INSTITUTION,TransferIntent.DELIVERY,"temple_test");}
    private TempleRecord temple(){return new TempleRecord(id,"test:church","Local church",store(1),store(2),new BlockPos(5,1,0),2,3,0);}
    private ReligionData data(){var d=new ReligionData();d.temple(temple());return d;}
    private AlmsCase request(){return new AlmsCase(UUID.randomUUID(),id,person,new ItemFingerprint("minecraft:bread",0),3,"declared hardship",AlmsCase.Stage.REQUESTED,null,null,null,0,0,0,0,null,"new");}
    @Test void bindingIsIdempotentAndCannotSwitchStores(){var d=data();var t=d.temple(id);d.temple(t);assertEquals(1,d.temples().size());assertThrows(IllegalStateException.class,()->d.temple(new TempleRecord(id,t.building(),t.name(),store(3),store(4),t.counter(),2,3,0)));}
    @Test void sameBuildingCannotHaveSecondInstitution(){var d=data();var t=d.temple(id);UUID second=UUID.randomUUID();var a=new FieldworkStorage(t.alms().dimension(),new BlockPos(8,1,0),UUID.randomUUID(),SubjectRef.institution(second),AccessPolicy.INSTITUTION,TransferIntent.DELIVERY,"other");var b=new FieldworkStorage(a.dimension(),new BlockPos(9,1,0),UUID.randomUUID(),a.owner(),a.policy(),a.intent(),a.authority());assertThrows(IllegalStateException.class,()->d.temple(new TempleRecord(second,t.building(),"Other",a,b,new BlockPos(10,1,0),0,3,0)));}
    @Test void treasuryAndAlmsCannotBeSameContainer(){var p=store(1);assertThrows(IllegalArgumentException.class,()->new TempleRecord(id,"church","Temple",p,p,new BlockPos(4,1,0),2,3,0));}
    @Test void impossibleReserveAndPortionRejected(){assertThrows(IllegalArgumentException.class,()->new TempleRecord(id,"church","Temple",store(1),store(2),new BlockPos(4,1,0),-1,3,0));assertThrows(IllegalArgumentException.class,()->new TempleRecord(id,"church","Temple",store(1),store(2),new BlockPos(4,1,0),2,65,0));}
    @Test void subjectAndQuantityCannotBeRewritten(){var d=data();var c=request();d.aid(c);assertThrows(IllegalStateException.class,()->d.aid(new AlmsCase(c.id(),id,UUID.randomUUID(),c.item(),3,c.statement(),c.stage(),null,null,null,0,0,0,0,null,"changed")));assertThrows(IllegalStateException.class,()->d.aid(new AlmsCase(c.id(),id,person,c.item(),4,c.statement(),c.stage(),null,null,null,0,0,0,0,null,"changed")));}
    @Test void aClaimCannotSwitchBody(){var d=data();var c=request().claim(UUID.randomUUID(),person);d.aid(c);assertThrows(IllegalStateException.class,()->d.aid(requestWith(c,UUID.randomUUID())));}
    private AlmsCase requestWith(AlmsCase c,UUID body){return new AlmsCase(c.id(),id,person,c.item(),c.quantity(),c.statement(),c.stage(),body,person,c.reviewer(),0,0,0,0,null,"new");}
    @Test void liveCargoCannotBecomeUnassigned(){var d=data();var c=request().claim(UUID.randomUUID(),person).update(AlmsCase.Stage.CARRYING,person,1,1,null,"carried",false);d.aid(c);assertThrows(IllegalStateException.class,()->d.aid(c.update(AlmsCase.Stage.APPROVED,person,2,2,null,"discard cargo",true)));}
    @Test void unprovenCarryingCannotLoadAsDelivered(){var d=data();var c=request().claim(UUID.randomUUID(),person).update(AlmsCase.Stage.CARRYING,person,1,1,null,"carried",false);d.aid(c);assertThrows(IllegalArgumentException.class,()->ReligionData.load(d.save(new CompoundTag(),null),null));}
    @Test void pendingTransactionAndReceiptsRoundTripExactly(){var d=data();var c=request().claim(UUID.randomUUID(),person);var p=new AlmsCase.Pending(UUID.randomUUID(),UUID.randomUUID(),false,3,4,5);c=c.update(AlmsCase.Stage.CARRYING,person,5,6,p,"pending",false);d.aid(c);d.receipt(c.id(),true,UUID.randomUUID());var restored=ReligionData.load(d.save(new CompoundTag(),null),null);assertEquals(c,restored.aid(c.id()));assertEquals(d.receipt(c.id(),true),restored.receipt(c.id(),true));}
    @Test void receiptCannotBeReplaced(){var d=data();var c=request();d.aid(c);UUID receipt=UUID.randomUUID();d.receipt(c.id(),true,receipt);d.receipt(c.id(),true,receipt);assertThrows(IllegalStateException.class,()->d.receipt(c.id(),true,UUID.randomUUID()));}
    @Test void finalizedCaseCannotBeReopened(){var d=data();var c=request().update(AlmsCase.Stage.DENIED,person,1,1,null,"rule denied",true);d.aid(c);assertThrows(IllegalStateException.class,()->d.aid(c.update(AlmsCase.Stage.REQUESTED,person,2,2,null,"retry",true)));}
    @Test void timeCannotMoveBackwards(){var c=request().update(AlmsCase.Stage.APPROVED,person,5,5,null,"approved",true);assertThrows(IllegalArgumentException.class,()->c.update(c.stage(),person,4,4,null,"old",true));}
    @Test void damagedOrDuplicateSchemaFailsClosed(){var d=data();var damaged=d.save(new CompoundTag(),null);damaged.remove("Transactions");assertThrows(IllegalArgumentException.class,()->ReligionData.load(damaged,null));var duplicate=d.save(new CompoundTag(),null);duplicate.getList("Temples",Tag.TAG_COMPOUND).add(duplicate.getList("Temples",Tag.TAG_COMPOUND).getCompound(0).copy());assertThrows(IllegalArgumentException.class,()->ReligionData.load(duplicate,null));}
    @Test void missingDonationComponentsIsNotDefaultFingerprint(){var d=data();var gift=new DonationRecord(UUID.randomUUID(),id,person,UUID.randomUUID(),d.temple(id).alms().containerId(),new ItemFingerprint("minecraft:bread",0),3,DonationRecord.Purpose.ALMS,DonationRecord.Status.PENDING,0,0,0,0,"consent");d.donation(gift);var tag=d.save(new CompoundTag(),null);tag.getList("Donations",Tag.TAG_COMPOUND).getCompound(0).getCompound("Item").remove("Components");assertThrows(IllegalArgumentException.class,()->ReligionData.load(tag,null));}
    @Test void donationIdentityAndFinalReceiptCannotChange(){var d=data();UUID giftId=UUID.randomUUID(),source=UUID.randomUUID();var gift=new DonationRecord(giftId,id,person,source,d.temple(id).alms().containerId(),new ItemFingerprint("minecraft:bread",0),3,DonationRecord.Purpose.ALMS,DonationRecord.Status.PENDING,0,0,0,0,"consent");d.donation(gift);d.donation(gift.result(DonationRecord.Status.RECORDED,1,"received"));assertThrows(IllegalStateException.class,()->d.donation(gift.result(DonationRecord.Status.FAILED,2,"rewrite")));}
    @Test void officeAuthoritiesAreNarrowAndRevocable(){var d=new InstitutionData();var rights=new RightsStateData();var founder=SubjectRef.character(person);InstitutionService.establish(d,rights,id,"Temple",InstitutionKind.TEMPLE,null,UUID.randomUUID(),founder,Set.of(OfficeAuthority.APPOINT_OFFICER,OfficeAuthority.MANAGE_TREASURY),0,"local");UUID steward=UUID.randomUUID();var office=InstitutionService.appoint(d,id,founder,SubjectRef.character(steward),"Deacon",Set.of(OfficeAuthority.MANAGE_ALMS),0,100);assertTrue(d.authority(SubjectRef.character(steward),id,OfficeAuthority.MANAGE_ALMS,1).allowed());assertFalse(d.authority(SubjectRef.character(steward),id,OfficeAuthority.MANAGE_TREASURY,1).allowed());assertFalse(d.authority(founder,id,OfficeAuthority.MANAGE_ALMS,1).allowed());d.revokeOffice(office.id());assertFalse(d.authority(SubjectRef.character(steward),id,OfficeAuthority.MANAGE_ALMS,2).allowed());}
}
